<?php
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/../includes/db.php';
$issued = $pdo->query("SELECT ib.id,ib.issue_date,ib.return_date,b.title,s.name AS student_name FROM issued_books ib JOIN books b ON b.id=ib.book_id JOIN students s ON s.id=ib.student_id WHERE ib.status='issued' ORDER BY ib.return_date,ib.id")->fetchAll();
$returned = $pdo->query("SELECT ib.id,ib.issue_date,ib.return_date,ib.returned_at,b.title,s.name AS student_name FROM issued_books ib JOIN books b ON b.id=ib.book_id JOIN students s ON s.id=ib.student_id WHERE ib.status='returned' ORDER BY ib.returned_at DESC,ib.id DESC LIMIT 100")->fetchAll();
$overdue = $pdo->query("SELECT ib.id,ib.issue_date,ib.return_date,b.title,s.name AS student_name,DATEDIFF(CURRENT_DATE,ib.return_date) AS days_overdue FROM issued_books ib JOIN books b ON b.id=ib.book_id JOIN students s ON s.id=ib.student_id WHERE ib.status='issued' AND ib.return_date<CURRENT_DATE ORDER BY ib.return_date")->fetchAll();
$pageTitle = 'Reports'; require __DIR__ . '/../includes/header.php';
?>
<div class="page-heading"><div><h1>Library reports</h1><p>Review current loans, completed returns, and overdue books.</p></div></div>
<ul class="nav nav-pills gap-2 mb-3" role="tablist"><li class="nav-item" role="presentation"><button class="nav-link active" data-bs-toggle="pill" data-bs-target="#overdue-report" type="button" role="tab">Overdue <span class="badge text-bg-danger ms-1"><?= count($overdue) ?></span></button></li><li class="nav-item" role="presentation"><button class="nav-link" data-bs-toggle="pill" data-bs-target="#issued-report" type="button" role="tab">Issued <span class="badge text-bg-light text-dark ms-1"><?= count($issued) ?></span></button></li><li class="nav-item" role="presentation"><button class="nav-link" data-bs-toggle="pill" data-bs-target="#returned-report" type="button" role="tab">Returned <span class="badge text-bg-light text-dark ms-1"><?= count($returned) ?></span></button></li></ul>
<div class="tab-content">
<div class="tab-pane fade show active" id="overdue-report" role="tabpanel"><div class="panel-card"><h2 class="panel-title">Overdue books</h2><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Book</th><th>Student</th><th>Due date</th><th>Days overdue</th></tr></thead><tbody><?php if (!$overdue): ?><tr><td colspan="4" class="text-center text-secondary py-4">No overdue books. Great work!</td></tr><?php endif; ?><?php foreach ($overdue as $row): ?><tr><td class="fw-semibold"><?= e($row['title']) ?></td><td><?= e($row['student_name']) ?></td><td><?= e($row['return_date']) ?></td><td><span class="badge text-bg-danger"><?= (int) $row['days_overdue'] ?> days</span></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<div class="tab-pane fade" id="issued-report" role="tabpanel"><div class="panel-card"><h2 class="panel-title">Currently issued books</h2><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Book</th><th>Student</th><th>Issue date</th><th>Due date</th><th>Status</th></tr></thead><tbody><?php if (!$issued): ?><tr><td colspan="5" class="text-center text-secondary py-4">No active loans.</td></tr><?php endif; ?><?php foreach ($issued as $row): $isOverdue = $row['return_date'] < date('Y-m-d'); ?><tr><td class="fw-semibold"><?= e($row['title']) ?></td><td><?= e($row['student_name']) ?></td><td><?= e($row['issue_date']) ?></td><td><?= e($row['return_date']) ?></td><td><span class="badge text-bg-<?= $isOverdue ? 'danger' : 'warning' ?>"><?= $isOverdue ? 'Overdue' : 'Issued' ?></span></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<div class="tab-pane fade" id="returned-report" role="tabpanel"><div class="panel-card"><h2 class="panel-title">Returned books <span class="small text-secondary fw-normal">(latest 100)</span></h2><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Book</th><th>Student</th><th>Issue date</th><th>Due date</th><th>Returned</th></tr></thead><tbody><?php if (!$returned): ?><tr><td colspan="5" class="text-center text-secondary py-4">No returned books yet.</td></tr><?php endif; ?><?php foreach ($returned as $row): ?><tr><td class="fw-semibold"><?= e($row['title']) ?></td><td><?= e($row['student_name']) ?></td><td><?= e($row['issue_date']) ?></td><td><?= e($row['return_date']) ?></td><td><?= e($row['returned_at'] ? substr($row['returned_at'], 0, 10) : '—') ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
</div>
